        ?? run.conversation.entries.findIndex((entry) => entry.kind === 'message' && entry.id === messageId);
    if (currentIndex < 0) {
        const initialContent = run.streaming ? content : content.replace(/^\n+|\n+$/g, '');
        const message = createMessageEntry(
            messageId,
            'assistant',
            initialContent,
